/** Wings whose snapshot outline carries no flat tags/config labels (no records; not inferred). */
export const UNLABELLED_WINGS: readonly number[] = [3, 5, 6, 7];

/**
 * Unit-count arithmetic vs the printed total (3,484; snapshot + masterplan). Typical floors: wings
 * 1, 2, 9-14 = 46, wings 3-8 = 45 (snapshot elevation + masterplan). The 6 flats/floor used for the
 * unlabelled wings 3, 5, 6, 7 is an ASSUMPTION for this check only. The printed total falls between
 * "refuge floors empty" and "refuge floors full"; refuge-floor flat counts are not printed, so the
 * gap cannot be closed from the sources.
 */
export const FLAT_COUNT_CHECK = {
  flatsPerFloor: { 1: 6, 2: 6, 4: 6, 8: 6, 9: 4, 10: 6, 11: 6, 12: 6, 13: 6, 14: 4 } as Record<number, number>,
  labelledWingsTotalIfAllFloorsFull: 2564,
  assumedFlatsPerFloorForUnlabelledWings: 6,
  allWingsTotalIfAllFloorsFull: 3644,
  allWingsTotalIfRefugeFloorsEmpty: 3404,
  printedTotal: 3484,
  gapToPrinted: 160,
  refugeWingFloors: 42,
  kind: 'estimated' as const,
};

/** All flat positions of one wing (empty for wings without snapshot labels). */
export function flatsForWing(wing: number): FlatRecord[] {
  return FLATS.filter((f) => f.wing === wing);
}

/** One flat position, or undefined if not on the snapshot. */
export function flatFor(wing: number, flat: number): FlatRecord | undefined {
  return FLATS.find((f) => f.wing === wing && f.flat === flat);
}
